  country_code TEXT NOT NULL,
  latitude DOUBLE PRECISION NOT NULL,
  longitude DOUBLE PRECISION NOT NULL,
  website TEXT,
  website_url TEXT,
  phone TEXT,
  slug TEXT NOT NULL,
  source_type TEXT NOT NULL DEFAULT 'seed_overture',
